<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue';
import { useRoute } from 'vue-router';
import type { LiveSourceConfig,SourceAuditResult,SourceConfig,SourceHealth,SourceKind } from '@free-new-desk/contracts';
import { listVodFavorites,saveVodFavorites } from '../favorites';
const route=useRoute();
const auditing=ref(new Set<string>());const checkingGroups=ref(new Set<string>());const groupDeleteBusy=ref(new Set<string>());const sourceOrder=ref<string[]>([]);const draggedSourceId=ref('');const sources=ref<SourceConfig[]>([]);const liveSources=ref<LiveSourceConfig[]>([]);const health=ref<SourceHealth[]>([]);const loading=ref(true);const bulkBusy=ref(false);const error=ref('');const importText=ref('');const importMessage=ref('');const audit=ref<SourceAuditResult|null>(null);const importTab=ref<'config'|'local-live'|'remote-live'>('config');const draft=reactive({name:'',endpoint:'',kind:'T1_JSON' as SourceKind,ext:'',jar:''});const liveDraft=reactive({name:'',url:'',epg:'',userAgent:''});const healthMap=computed(()=>new Map(health.value.map(item=>[item.sourceId,item])));const isExecutable=(kind:SourceKind)=>kind==='T3_JS'||kind==='T3_JAR'||kind==='PLUGIN'||kind==='T4_CATVOD';const enabledCount=computed(()=>sources.value.filter(item=>item.enabled).length+liveSources.value.filter(item=>item.enabled).length);const passedCount=computed(()=>health.value.filter(item=>item.ok).length);const confirmCount=computed(()=>sources.value.filter(item=>item.trust==='B').length);const totalCount=computed(()=>sources.value.length+liveSources.value.length);const enabledPercent=computed(()=>totalCount.value?Math.round(enabledCount.value/totalCount.value*100):0);const passedPercent=computed(()=>totalCount.value?Math.round(passedCount.value/totalCount.value*100):0);const confirmPercent=computed(()=>sources.value.length?Math.round(confirmCount.value/sources.value.length*100):0);
type GroupKey='api'|'rule'|'spider';const groupMeta:Record<GroupKey,{label:string;description:string}>={api:{label:'接口类来源',description:'CMS XML / JSON / Type4 等声明式接口'},rule:{label:'规则与网盘',description:'XYQ / XBPQ / AList 等规则或索引来源'},spider:{label:'Spider / 可执行来源',description:'JS / CatVod / JAR / Plugin，启用前需确认信任'}};function groupKey(kind:SourceKind):GroupKey{if(kind==='T0_XML'||kind==='T1_JSON'||kind==='T4_EXT')return'api';if(kind==='T3_XYQ'||kind==='T3_XBPQ'||kind==='DRIVE_ALIST')return'rule';return'spider';}const sourceGroups=computed(()=>Object.entries(groupMeta).map(([key,meta])=>({key:key as GroupKey,...meta,items:sources.value.filter(source=>groupKey(source.kind)===key).sort((a,b)=>{const ai=sourceOrder.value.indexOf(a.id),bi=sourceOrder.value.indexOf(b.id);return(ai<0?999999:ai)-(bi<0?999999:bi);})})).filter(group=>group.items.length>0));
const liveOriginMeta={local:{label:'本地播放列表',origins:['local-file']},remote:{label:'网络播放列表',origins:['remote-playlist']},tvbox:{label:'TVBox / FongMi 配置直播',origins:['tvbox']},other:{label:'其他直播来源',origins:['manual',undefined]}} as const;const liveGroups=computed(()=>Object.entries(liveOriginMeta).map(([key,meta])=>({key,label:meta.label,items:liveSources.value.filter(item=>(meta.origins as readonly (string|undefined)[]).includes(item.origin))})).filter(group=>group.items.length));
interface ImportGroup{id:string;label:string;importedAt:string;pointSources:SourceConfig[];liveSources:LiveSourceConfig[];compatible:number;incompatible:number;pending:number;}
const importGroups=computed<ImportGroup[]>(()=>{const groups=new Map<string,ImportGroup>();const ensure=(id:string,label:string,importedAt:string)=>{let group=groups.get(id);if(!group){group={id,label,importedAt,pointSources:[],liveSources:[],compatible:0,incompatible:0,pending:0};groups.set(id,group);}return group;};for(const source of sources.value)if(source.importGroupId)ensure(source.importGroupId,source.sourceLabel??'导入配置',source.importedAt??'').pointSources.push(source);for(const source of liveSources.value)if(source.importGroupId)ensure(source.importGroupId,source.sourceLabel??source.name,source.importedAt??'').liveSources.push(source);for(const group of groups.values())for(const source of [...group.pointSources,...group.liveSources]){const item=healthMap.value.get(source.id);if(!item)group.pending+=1;else if(item.ok)group.compatible+=1;else group.incompatible+=1;}return[...groups.values()].sort((a,b)=>b.importedAt.localeCompare(a.importedAt));});
const compatibilityFilter=ref<'all'|'compatible'|'incompatible'|'pending'>('all');const compatibilityRows=computed(()=>{const rows=[...sources.value.map(source=>({source,type:'点播',group:source.importGroupId?(importGroups.value.find(item=>item.id===source.importGroupId)?.label??'导入配置'):'未归组'})),...liveSources.value.map(source=>({source,type:'直播',group:source.importGroupId?(importGroups.value.find(item=>item.id===source.importGroupId)?.label??'导入配置'):'未归组'}))].map(row=>({...row,health:healthMap.value.get(row.source.id)}));if(compatibilityFilter.value==='compatible')return rows.filter(row=>row.health?.ok===true);if(compatibilityFilter.value==='incompatible')return rows.filter(row=>row.health?.ok===false);if(compatibilityFilter.value==='pending')return rows.filter(row=>!row.health);return rows;});
function originLabel(source:LiveSourceConfig){if(source.origin==='local-file')return'本地文件';if(source.origin==='remote-playlist')return'网络 URL';if(source.origin==='tvbox')return'TVBox/FongMi';return'手工';}
const editDraft=reactive({id:'',name:'',endpoint:'',ext:'',jar:''});const editLiveDraft=reactive({id:'',name:'',epg:'',userAgent:''});const editOpen=ref(false);const editLiveOpen=ref(false);
function openEdit(source:SourceConfig){editDraft.id=source.id;editDraft.name=source.name;editDraft.endpoint=source.endpoint;editDraft.ext=source.ext??'';editDraft.jar=source.jar??'';editOpen.value=true;}
async function saveEdit(){error.value='';const source=sources.value.find(item=>item.id===editDraft.id);if(!source){editOpen.value=false;return;}try{await window.desktop.source.save({...source,name:editDraft.name.trim()||source.name,endpoint:editDraft.endpoint.trim()||source.endpoint,...(editDraft.ext.trim()?{ext:editDraft.ext.trim()}:{ext:undefined}),...(editDraft.jar.trim()?{jar:editDraft.jar.trim()}:{jar:undefined})});editOpen.value=false;importMessage.value=`来源「${source.name}」已保存。`;await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}}
function openEditLive(source:LiveSourceConfig){editLiveDraft.id=source.id;editLiveDraft.name=source.name;editLiveDraft.epg=source.epg??'';editLiveDraft.userAgent=source.headers?.['User-Agent']??'';editLiveOpen.value=true;}
async function saveEditLive(){error.value='';const source=liveSources.value.find(item=>item.id===editLiveDraft.id);if(!source){editLiveOpen.value=false;return;}try{const headers=editLiveDraft.userAgent.trim()?{'User-Agent':editLiveDraft.userAgent.trim()}:undefined;await window.desktop.live.saveSource({...source,name:editLiveDraft.name.trim()||source.name,...(editLiveDraft.epg.trim()?{epg:editLiveDraft.epg.trim()}:{}),...(headers?{headers}:{headers:undefined})});editLiveOpen.value=false;importMessage.value=`直播来源「${source.name}」已保存。`;await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}}
type DeleteDraft={kind:'vod'|'live'|'group';id:string;name:string;confirmText:string;counts:Array<{label:string;count:number}>};
const deleteDraft=ref<DeleteDraft|null>(null);
function deleteReady(){return Boolean(deleteDraft.value&&deleteDraft.value.confirmText===deleteDraft.value.name);}
async function requestRemove(source:SourceConfig){error.value='';try{const [favorites,history]=await Promise.all([listVodFavorites().catch(()=>[]),window.desktop.history.list(1000).catch(()=>[])]);deleteDraft.value={kind:'vod',id:source.id,name:source.name,confirmText:'',counts:[{label:'点播来源本身',count:1},{label:'关联收藏',count:favorites.filter(item=>item.sourceId===source.id).length},{label:'关联播放历史',count:history.filter(item=>item.sourceId===source.id).length}]};}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function requestRemoveLive(source:LiveSourceConfig){error.value='';try{const [channels,favorites,reservations,epg]=await Promise.all([window.desktop.live.channels(source.id).catch(()=>[]),window.desktop.live.favorites().then(items=>items.filter(item=>item.liveSourceId===source.id)).catch(()=>[]),window.desktop.reservation.list().then(items=>items.filter(item=>item.liveSourceId===source.id)).catch(()=>[]),window.desktop.epg.list(source.id).catch(()=>[])]);deleteDraft.value={kind:'live',id:source.id,name:source.name,confirmText:'',counts:[{label:'直播频道',count:channels.reduce((sum,group)=>sum+group.channels.length,0)},{label:'直播收藏',count:favorites.length},{label:'节目预约',count:reservations.length},{label:'EPG 节目单条目',count:epg.length},...(source.origin==='local-file'?[{label:'托管的播放列表文件',count:1}]:[])]};}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function deleteImportGroup(group:ImportGroup){const removedIds=new Set(group.pointSources.map(item=>item.id));if(removedIds.size){const favorites=await listVodFavorites().catch(()=>[]);await saveVodFavorites(favorites.filter(item=>!removedIds.has(item.sourceId)));}const result=await window.desktop.source.removeImportGroup(group.id);if(removedIds.has(localStorage.getItem('vod.sourceId')??''))localStorage.removeItem('vod.sourceId');if(group.liveSources.some(item=>item.id===localStorage.getItem('live.sourceId')))localStorage.removeItem('live.sourceId');importMessage.value=`导入源「${group.label}」已删除：${result.pointSources} 个点播、${result.liveSources} 个直播及全部关联数据。`;await reload();}
async function requestRemoveGroup(group:ImportGroup){if(checkingGroups.value.has(group.id)||groupDeleteBusy.value.has(group.id))return;const total=group.pointSources.length+group.liveSources.length;if(!window.confirm(`确认一键删除导入源「${group.label}」？\n\n将删除 ${group.pointSources.length} 个点播来源、${group.liveSources.length} 个直播来源（共 ${total} 个）以及关联的兼容性、历史、收藏、EPG 和预约数据。此操作不可恢复。`))return;const next=new Set(groupDeleteBusy.value);next.add(group.id);groupDeleteBusy.value=next;error.value='';importMessage.value=`正在删除导入源「${group.label}」…`;try{await deleteImportGroup(group);}catch(value){error.value=value instanceof Error?value.message:String(value);importMessage.value=`删除导入源「${group.label}」失败。`;}finally{const done=new Set(groupDeleteBusy.value);done.delete(group.id);groupDeleteBusy.value=done;}}
async function confirmDelete(){const draft=deleteDraft.value;if(!draft||!deleteReady())return;deleteDraft.value=null;try{if(draft.kind==='vod')await remove(sources.value.find(item=>item.id===draft.id) as SourceConfig);else if(draft.kind==='live')await removeLive(liveSources.value.find(item=>item.id===draft.id) as LiveSourceConfig);else{const group=importGroups.value.find(item=>item.id===draft.id);if(!group)throw new Error('导入源不存在或已经删除');await deleteImportGroup(group);}}catch(value){error.value=value instanceof Error?value.message:String(value);}}
const bulkHealthBusy=ref(false);const bulkHealthProgress=ref('');let bulkHealthCancel=false;
async function runBulkHealth(){if(bulkHealthBusy.value){bulkHealthCancel=true;return;}const targets=sources.value.filter(item=>item.enabled);if(!targets.length){error.value='没有已启用的点播来源可检测。';return;}bulkHealthCancel=false;bulkHealthBusy.value=true;error.value='';const next=new Set<string>();try{for(let index=0;index<targets.length;index++){const source=targets[index]!;if(bulkHealthCancel){bulkHealthProgress.value=`已取消（${index}/${targets.length}）`;return;}bulkHealthProgress.value=`健康检测中 ${index+1}/${targets.length} · ${source.name}`;next.add(source.id);auditing.value=new Set(next);try{audit.value=await window.desktop.source.audit(source.id);health.value=await window.desktop.source.health();}catch(value){error.value=value instanceof Error?value.message:String(value);}finally{next.delete(source.id);}}bulkHealthProgress.value=`健康检测完成：${targets.length} 个来源`;importMessage.value=bulkHealthProgress.value;}finally{bulkHealthBusy.value=false;auditing.value=new Set();}}
async function reload(){loading.value=true;error.value='';try{const [pointValues,liveValues,healthValues,settings]=await Promise.all([window.desktop.source.list(),window.desktop.live.listSources(),window.desktop.source.health(),window.desktop.settings.list()]);sources.value=pointValues;liveSources.value=liveValues;health.value=healthValues;try{const parsed=JSON.parse(settings['source.order']??'[]') as unknown;sourceOrder.value=Array.isArray(parsed)?parsed.filter((item):item is string=>typeof item==='string'):[];}catch{sourceOrder.value=[];}}catch(value){error.value=value instanceof Error?value.message:String(value);}finally{loading.value=false;}}
async function moveSource(targetId:string){const sourceId=draggedSourceId.value;if(!sourceId||sourceId===targetId)return;const order=[...sourceOrder.value,...sources.value.map(item=>item.id).filter(id=>!sourceOrder.value.includes(id))];const from=order.indexOf(sourceId),to=order.indexOf(targetId);if(from<0||to<0)return;order.splice(from,1);order.splice(to,0,sourceId);sourceOrder.value=order;draggedSourceId.value='';await window.desktop.settings.set('source.order',JSON.stringify(order));}
async function addSource(){error.value='';try{const executable=isExecutable(draft.kind);await window.desktop.source.save({id:crypto.randomUUID(),name:draft.name.trim(),endpoint:draft.endpoint.trim(),kind:draft.kind,enabled:!executable,trust:executable?'B':'A',...(draft.ext.trim()?{ext:draft.ext.trim()}:{}),...(draft.jar.trim()?{jar:draft.jar.trim()}:{})});draft.name='';draft.endpoint='';draft.ext='';draft.jar='';importMessage.value=executable?'可执行来源已按 Level B 添加并保持停用；请确认信任后手动启用。':'';await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function toggle(source:SourceConfig){if(!source.enabled&&source.trust==='B'&&!window.confirm('此来源包含可执行脚本或代码，仅启用你信任的来源。是否继续？'))return;await window.desktop.source.save({...source,enabled:!source.enabled});await reload();}async function toggleLive(source:LiveSourceConfig){await window.desktop.live.saveSource({...source,enabled:!source.enabled});await reload();}
async function remove(source:SourceConfig){await window.desktop.source.remove(source.id);importMessage.value=`点播来源「${source.name}」及其关联数据已删除。`;await reload();}async function removeLive(source:LiveSourceConfig){await window.desktop.live.removeSource(source.id);importMessage.value=`直播来源「${source.name}」已级联删除（频道、收藏、EPG、预约与托管文件）。`;await reload();}
function dialogEscape(event:KeyboardEvent){if(event.key!=='Escape')return;deleteDraft.value=null;editOpen.value=false;editLiveOpen.value=false;}
const onlyUnhealthy=ref(false);
function visibleItems(items:SourceConfig[]):SourceConfig[]{return onlyUnhealthy.value?items.filter(item=>healthMap.value.get(item.id)?.ok===false):items;}
onMounted(()=>{window.addEventListener('keydown',dialogEscape);if(route.query.filter==='unhealthy')onlyUnhealthy.value=true;void reload();});
onBeforeUnmount(()=>{window.removeEventListener('keydown',dialogEscape);});
function compatibilitySummary(items:{compatible:boolean}[]|undefined){const values=items??[],compatible=values.filter(item=>item.compatible).length;return`兼容 ${compatible} 个，不兼容 ${values.length-compatible} 个`;}
async function importConfig(){error.value='';importMessage.value='正在导入并逐来源检查兼容性…';try{const result=await window.desktop.config.importText(importText.value);importMessage.value='已导入 '+result.sources.length+' 个点播源、'+result.liveSources.length+' 个直播源；'+compatibilitySummary(result.compatibility)+(result.warnings.length?'；'+result.warnings.join('；'):'');importText.value='';await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function importConfigFile(){error.value='';importMessage.value='正在导入并逐来源检查兼容性…';try{const result=await window.desktop.config.importFile();if(!result.canceled&&result.result){importMessage.value='本地配置已导入：'+result.result.sources.length+' 个点播源、'+result.result.liveSources.length+' 个直播源；'+compatibilitySummary(result.result.compatibility);await reload();}}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function importLiveFile(){error.value='';importMessage.value='正在导入并检查直播来源兼容性…';try{const result=await window.desktop.live.importFile();if(!result.canceled){importMessage.value='本地直播列表已导入，共 '+(result.channelCount??0)+' 个频道；'+compatibilitySummary(result.compatibility);await reload();}}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function importLiveUrl(){error.value='';importMessage.value='正在导入并检查直播来源兼容性…';try{const result=await window.desktop.live.importUrl({url:liveDraft.url.trim(),...(liveDraft.name.trim()?{name:liveDraft.name.trim()}:{}),...(liveDraft.epg.trim()?{epg:liveDraft.epg.trim()}:{}),...(liveDraft.userAgent.trim()?{userAgent:liveDraft.userAgent.trim()}:{})});importMessage.value='网络直播列表已导入，共 '+result.channelCount+' 个频道；'+compatibilitySummary(result.compatibility);liveDraft.name='';liveDraft.url='';liveDraft.epg='';liveDraft.userAgent='';await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}}
async function checkGroup(group:ImportGroup){const next=new Set(checkingGroups.value);next.add(group.id);checkingGroups.value=next;error.value='';importMessage.value=`正在重新检查「${group.label}」的 ${group.pointSources.length+group.liveSources.length} 个来源…`;try{const results=await window.desktop.source.checkImportGroup(group.id);importMessage.value=`「${group.label}」检查完成：${compatibilitySummary(results)}`;health.value=await window.desktop.source.health();}catch(value){error.value=value instanceof Error?value.message:String(value);}finally{const done=new Set(checkingGroups.value);done.delete(group.id);checkingGroups.value=done;}}
async function runAudit(source:SourceConfig){const next=new Set(auditing.value);next.add(source.id);auditing.value=next;error.value='';try{audit.value=await window.desktop.source.audit(source.id);health.value=await window.desktop.source.health();}catch(value){error.value=value instanceof Error?value.message:String(value);}finally{const done=new Set(auditing.value);done.delete(source.id);auditing.value=done;}}
async function exportAudit(sourceId:string){error.value='';try{const result=await window.desktop.source.exportAudit(sourceId);importMessage.value=result.canceled?'已取消导出':`审计报告已导出：${result.path??''}`;}catch(value){error.value=value instanceof Error?value.message:String(value);}}
function fillExample(){importText.value='https://raw.githubusercontent.com/cwe88108/free-new-desk-public/main/examples/tvbox-sample.json';importMessage.value='这是本项目维护的最小 TVBox 示例配置；导入远程配置前仍会要求确认域名。';}
async function copySource(source:SourceConfig){await window.desktop.app.action({copy:source.endpoint});importMessage.value='来源地址已复制';}
function compatibilityTip(message:string|undefined){if(!message)return'';if(/ClassNotFoundException/i.test(message))return'配置指定的 Spider 类不在当前 JAR 中，请更换匹配的 spider JAR 或停用该来源。';if(/timeout|timed out/i.test(message))return'来源响应超时，可检查网络、UA/Referer 或降低该来源优先级。';if(/403|forbidden/i.test(message))return'来源拒绝访问，通常需要正确的 User-Agent、Referer、Cookie 或来源已失效。';if(/format|parse/i.test(message))return'返回格式与声明类型不匹配，请核对接口类型或规则。';return message;}
function compatibilityLabel(sourceId:string){const item=healthMap.value.get(sourceId);return!item?'待检查':item.ok?'兼容':'不兼容';}
function compatibilityClass(sourceId:string){const item=healthMap.value.get(sourceId);return{safe:item?.ok===true,danger:item?.ok===false,pending:!item};}
function confirmBulk(items:SourceConfig[],enabled:boolean):boolean{return!enabled||!items.some(source=>source.trust==='B'&&!source.enabled)||window.confirm('批量启用将包含 Level B 可执行来源。仅在你信任这些来源时继续。是否继续？');}
async function applyBulk(pointItems:SourceConfig[],liveItems:LiveSourceConfig[],enabled:boolean,label:string){if(!confirmBulk(pointItems,enabled))return;bulkBusy.value=true;error.value='';try{const pointTargets=pointItems.filter(source=>source.enabled!==enabled),liveTargets=liveItems.filter(source=>source.enabled!==enabled);const result=await window.desktop.source.setEnabledBulk({vodSourceIds:pointTargets.map(item=>item.id),liveSourceIds:liveTargets.map(item=>item.id),enabled});for(const source of pointTargets)source.enabled=enabled;for(const source of liveTargets)source.enabled=enabled;importMessage.value=label+'完成：修改 '+result.changed+' 个，未变化 '+result.unchanged+' 个，失败 '+result.failed.length+' 个。';if(result.failed.length)error.value=result.failed.slice(0,3).map(item=>item.sourceId+'：'+item.reason).join('；');await reload();}catch(value){error.value=value instanceof Error?value.message:String(value);}finally{bulkBusy.value=false;}}
async function setPointSources(items:SourceConfig[],enabled:boolean){await applyBulk(items,[],enabled,enabled?'启动本组':'停用本组');}
async function setLiveSources(enabled:boolean){await applyBulk([],liveSources.value,enabled,enabled?'启动全部直播来源':'停用全部直播来源');}
async function setAll(enabled:boolean){await applyBulk(sources.value,liveSources.value,enabled,enabled?'全部启动':'全部停用');}
async function setCompatibilitySources(compatible:boolean,enabled:boolean,label:string){const ids=new Set(health.value.filter(item=>item.ok===compatible).map(item=>item.sourceId));const point=sources.value.filter(item=>ids.has(item.id)),live=liveSources.value.filter(item=>ids.has(item.id));if(point.length+live.length===0){importMessage.value=compatible?'没有已确认兼容的来源可启用。':'没有已确认不兼容的来源可停用。';return;}await applyBulk(point,live,enabled,label);}
</script>

<template><section class="page sources-page"><section class="page-banner"><div><h1>来源管理</h1><p>点播配置与 IPTV 播放列表分开管理；直播频道始终归属于导入来源。</p></div><blockquote>广收并蓄，择善而从。<br/><span>优质来源，让体验更稳定。</span></blockquote><div class="banner-stilllife"><i/><b/></div></section>
<div class="source-top-grid"><article class="panel import-console"><div class="panel-heading"><div><span class="panel-kicker">导入中心</span><h2>配置 / 本地 IPTV / 网络 IPTV</h2></div></div><div class="import-tabs"><button :class="{active:importTab==='config'}" @click="importTab='config'">TVBox 配置</button><button :class="{active:importTab==='local-live'}" @click="importTab='local-live'">本地直播列表</button><button :class="{active:importTab==='remote-live'}" @click="importTab='remote-live'">网络直播列表</button></div><template v-if="importTab==='config'"><textarea v-model="importText" rows="4" placeholder="输入 TVBox / FongMi 配置 URL，或直接粘贴 JSON"></textarea><div class="row-actions"><button class="primary-button" :disabled="!importText.trim()" @click="importConfig">导入配置</button><button class="secondary-button" @click="importConfigFile">选择本地配置</button><button class="text-link" @click="fillExample">示例</button><details class="inline-details"><summary>手工添加点播来源</summary><div class="manual-source-form"><input v-model="draft.name" placeholder="名称"/><select v-model="draft.kind"><option value="T1_JSON">CMS JSON</option><option value="T0_XML">CMS XML</option><option value="T4_EXT">Type4</option><option value="T3_JS">JS Spider / Drpy</option><option value="T3_XYQ">XYQ</option><option value="T3_XBPQ">XBPQ</option><option value="DRIVE_ALIST">Alist</option><option value="T3_JAR">Java JAR</option><option value="PLUGIN">本地插件</option></select><input v-model="draft.endpoint" placeholder="API / Endpoint / Manifest"/><input v-model="draft.ext" placeholder="Ext / 规则 / JS URL"/><input v-if="draft.kind==='T3_JAR'" v-model="draft.jar" placeholder="JAR 路径或 URL"/><button class="secondary-button" :disabled="!draft.name.trim()||!draft.endpoint.trim()" @click="addSource">添加</button></div></details></div></template><template v-else-if="importTab==='local-live'"><div class="drop-import"><strong>M3U / M3U8 / TXT / JSON</strong><p>文件会复制到应用托管目录并作为独立直播来源。删除该来源会同步删除其频道、收藏、EPG/预约数据和托管文件。</p><button class="primary-button" @click="importLiveFile">选择本地播放列表</button></div></template><template v-else><div class="remote-live-form"><input v-model="liveDraft.name" placeholder="来源名称（可选）"/><input v-model="liveDraft.url" placeholder="https://example.com/playlist.m3u"/><input v-model="liveDraft.epg" placeholder="XMLTV EPG URL（可选）"/><input v-model="liveDraft.userAgent" placeholder="自定义 User-Agent（可选）"/><button class="primary-button" :disabled="!liveDraft.url.trim()" @click="importLiveUrl">导入网络播放列表</button></div></template><small class="helper-text">{{importMessage||'软件不预置第三方影视或直播内容；所有播放列表由用户自行导入。'}}</small></article><section class="source-summary"><article><small>全部来源</small><strong>{{totalCount}}</strong><span>点播 + 直播 · 100%</span></article><article><small>已启用</small><strong>{{enabledCount}}</strong><span>占全部来源 {{enabledPercent}}%</span></article><article><small>通过审计</small><strong>{{passedCount}}</strong><span>占点播来源 {{passedPercent}}%</span></article><article><small>需人工确认</small><strong>{{confirmCount}}</strong><span>Level B · {{confirmPercent}}%</span></article></section></div>
<section class="panel import-groups-panel"><div class="panel-heading"><div><span class="panel-kicker">导入源</span><h2>按导入批次管理与兼容性检查</h2></div><small>删除导入源会级联删除其全部点播、直播及关联数据</small></div><div v-if="loading" class="loading-panel">正在读取导入源…</div><div v-else-if="importGroups.length===0" class="compact-empty">现有旧来源没有导入批次信息；新导入配置会在这里统一管理。</div><div v-else class="import-group-list"><article v-for="group in importGroups" :key="group.id" class="import-group-card"><div class="import-group-copy"><strong>{{group.label}}</strong><small>{{group.importedAt?new Date(group.importedAt).toLocaleString():'导入时间未知'}} · 点播 {{group.pointSources.length}} · 直播 {{group.liveSources.length}}</small></div><div class="compatibility-summary"><span class="compat-badge compatible">兼容 {{group.compatible}}</span><span class="compat-badge incompatible">不兼容 {{group.incompatible}}</span><span v-if="group.pending" class="compat-badge pending">待检查 {{group.pending}}</span></div><div class="table-actions"><button :disabled="checkingGroups.has(group.id)||groupDeleteBusy.has(group.id)" @click="checkGroup(group)">{{checkingGroups.has(group.id)?'检查中…':'重新检查全部'}}</button><button class="danger-link" :disabled="checkingGroups.has(group.id)||groupDeleteBusy.has(group.id)" @click="requestRemoveGroup(group)">{{groupDeleteBusy.has(group.id)?'删除中…':'一键删除源'}}</button></div></article></div></section>
<section class="panel compatibility-results-panel"><div class="panel-heading"><div><span class="panel-kicker">检查结果</span><h2>逐来源兼容性明细 · {{compatibilityRows.length}} 项</h2></div><div class="compat-filter"><button :class="{active:compatibilityFilter==='all'}" @click="compatibilityFilter='all'">全部</button><button :class="{active:compatibilityFilter==='compatible'}" @click="compatibilityFilter='compatible'">兼容</button><button :class="{active:compatibilityFilter==='incompatible'}" @click="compatibilityFilter='incompatible'">不兼容</button><button :class="{active:compatibilityFilter==='pending'}" @click="compatibilityFilter='pending'">待检查</button></div></div><div class="compatibility-table-wrap"><table class="source-table compatibility-table"><thead><tr><th>来源</th><th>类型</th><th>所属导入源</th><th>结果</th><th>阶段 / 耗时</th><th>原因与处理建议</th><th>检查时间</th></tr></thead><tbody><tr v-for="row in compatibilityRows" :key="row.type+row.source.id"><td><strong>{{row.source.name}}</strong><small>{{row.source.id}}</small></td><td>{{row.type}}</td><td><span class="group-label" :title="row.group">{{row.group}}</span></td><td><span class="compat-badge" :class="compatibilityClass(row.source.id)">{{compatibilityLabel(row.source.id)}}</span></td><td>{{row.health?.compatibilityStage??'—'}}<small v-if="row.health">{{row.health.latencyMs}}ms · {{row.health.retryable?'可重试':'已确认'}}</small></td><td><span class="compat-reason">{{compatibilityTip(row.health?.failureReason??row.health?.message)||'尚未执行兼容性检查'}}</span></td><td>{{row.health?.checkedAt?new Date(row.health.checkedAt).toLocaleString():'—'}}</td></tr></tbody></table></div></section>
<div class="bulk-toolbar panel"><div><span class="panel-kicker">全局控制</span><strong>一键启动 / 停用所有来源</strong></div><div class="row-actions"><button class="primary-button" :disabled="bulkBusy||totalCount===0" @click="setAll(true)">全部启动</button><button class="secondary-button" :disabled="bulkBusy||totalCount===0" @click="setAll(false)">全部停用</button><button class="secondary-button" :disabled="bulkBusy||passedCount===0" @click="setCompatibilitySources(true,true,'启用兼容来源')">启用兼容来源</button><button class="secondary-button" :disabled="bulkBusy||health.filter(item=>item.ok===false).length===0" @click="setCompatibilitySources(false,false,'停止不兼容来源')">停止不兼容来源</button><button class="secondary-button" :disabled="bulkHealthBusy||sources.length===0" :title="bulkHealthBusy?'点击取消剩余检测':''" @click="runBulkHealth">{{bulkHealthBusy?'停止检测':'健康检测（全部）'}}</button><button class="secondary-button" :disabled="bulkBusy" @click="reload">刷新</button><label class="unhealthy-toggle"><input v-model="onlyUnhealthy" type="checkbox"/>仅显示异常来源</label></div><small v-if="bulkHealthProgress" class="health-progress">{{bulkHealthProgress}}</small></div><p v-if="error" class="error-banner">{{error}}</p>
<div class="source-workspace"><section class="panel source-table-panel"><div class="panel-heading"><div><span class="panel-kicker">点播来源</span><h2>按大类分组 · 共 {{sources.length}} 个</h2></div></div><div v-if="loading" class="loading-panel">正在读取来源…</div><div v-else-if="sources.length===0" class="compact-empty">尚未添加点播来源。</div><div v-else class="source-table-wrap"><table class="source-table"><thead><tr><th>来源名称</th><th>来源类型</th><th>配置 / 播放策略</th><th>信任等级</th><th>兼容性 / 评分</th><th>最后检查</th><th>启用</th><th>操作</th></tr></thead><template v-for="group in sourceGroups" :key="group.key"><tbody class="source-group-body"><tr class="source-group-row"><td colspan="8"><div class="source-group-heading"><div><strong>{{group.label}}</strong><small>{{group.description}} · {{group.items.length}} 个</small></div><div class="table-actions"><button :disabled="bulkBusy" @click="setPointSources(group.items,true)">启动本组</button><button :disabled="bulkBusy" @click="setPointSources(group.items,false)">停用本组</button></div></div></td></tr><tr v-for="source in visibleItems(group.items)" :key="source.id" draggable="true" @dragstart="draggedSourceId=source.id" @dragover.prevent @drop="moveSource(source.id)"><td><span class="drag-handle" title="拖拽排序">⋮⋮</span><strong>{{source.name}}</strong><small>{{source.searchable===false?'不参与搜索':'可搜索'}}</small></td><td>{{source.kind}}</td><td><small>配置：{{source.configShell??'plain'}}</small><small>{{source.playUrl?'Parser':'Resolver'}}{{source.playerType!==undefined?' · P'+source.playerType:''}}</small></td><td><span class="trust-badge" :class="source.trust==='A'?'safe':'warn'">Level {{source.trust}}</span></td><td><span class="compat-badge" :class="compatibilityClass(source.id)">{{compatibilityLabel(source.id)}}</span><small v-if="healthMap.get(source.id)">{{healthMap.get(source.id)?.score??0}} 分 · {{healthMap.get(source.id)?.compatibilityStage??'invoke'}} · {{healthMap.get(source.id)?.retryable?'可重试':'已确认'}}</small><small v-if="healthMap.get(source.id)?.failureReason" class="compat-tip">{{compatibilityTip(healthMap.get(source.id)?.failureReason)}}</small></td><td>{{healthMap.get(source.id)?.checkedAt?new Date(healthMap.get(source.id)!.checkedAt).toLocaleString():'—'}}</td><td><button class="switch" :class="{on:source.enabled}" @click="toggle(source)"><i/></button></td><td><div class="table-actions"><button :disabled="!source.enabled||auditing.has(source.id)" @click="runAudit(source)">{{auditing.has(source.id)?'审计中…':'审计'}}</button><button @click="toggle(source)">{{source.enabled?'停用':'启用'}}</button><button @click="openEdit(source)">编辑</button><details class="source-more"><summary aria-label="更多操作">…</summary><button @click="copySource(source)">复制地址</button><button @click="exportAudit(source.id)">导出审计</button><button class="danger-link" @click="requestRemove(source)">删除</button></details></div></td></tr></tbody></template></table></div>
<div class="live-source-heading"><div><span class="panel-kicker">直播播放列表</span><h2>按导入来源归组 · 共 {{liveSources.length}} 个</h2></div><div class="table-actions"><button :disabled="bulkBusy||liveSources.length===0" @click="setLiveSources(true)">启动直播</button><button :disabled="bulkBusy||liveSources.length===0" @click="setLiveSources(false)">停用直播</button></div></div><div v-if="!loading&&liveSources.length===0" class="compact-empty">当前没有直播播放列表。可从上方直接导入 M3U/M3U8/TXT/JSON。</div><template v-for="group in liveGroups" :key="group.key"><div class="playlist-group-title"><strong>{{group.label}}</strong><small>{{group.items.length}} 个来源</small></div><div class="source-table-wrap"><table class="source-table live-source-table"><thead><tr><th>直播来源</th><th>来源方式</th><th>地址 / 文件</th><th>兼容性</th><th>EPG</th><th>导入时间</th><th>启用</th><th>操作</th></tr></thead><tbody><tr v-for="source in group.items" :key="source.id"><td><strong>{{source.name}}</strong></td><td><span class="trust-badge safe">{{originLabel(source)}}</span></td><td><code :title="source.sourceLabel||source.endpoint">{{source.sourceLabel||source.endpoint}}</code></td><td><span class="compat-badge" :class="compatibilityClass(source.id)">{{compatibilityLabel(source.id)}}</span><small v-if="healthMap.get(source.id)">{{healthMap.get(source.id)?.compatibilityStage??'network'}} · {{healthMap.get(source.id)?.retryable?'可重试':'已确认'}}</small><small v-if="healthMap.get(source.id)?.failureReason" class="compat-tip">{{compatibilityTip(healthMap.get(source.id)?.failureReason)}}</small></td><td>{{source.epg?'已配置':'—'}}</td><td>{{source.importedAt?new Date(source.importedAt).toLocaleString():'—'}}</td><td><button class="switch" :class="{on:source.enabled}" @click="toggleLive(source)"><i/></button></td><td><div class="table-actions"><button @click="openEditLive(source)">编辑</button><button @click="toggleLive(source)">{{source.enabled?'停用':'启用'}}</button><button class="danger-link" @click="requestRemoveLive(source)">删除整个来源</button></div></td></tr></tbody></table></div></template></section>
<aside class="panel audit-rail"><div class="panel-heading"><div><span class="panel-kicker">来源审计</span><h2>{{audit?.sourceId??'选择来源审计'}}</h2></div><div v-if="audit" class="audit-heading-actions"><button class="text-link" @click="exportAudit(audit.sourceId)">导出报告</button><span class="trust-badge" :class="audit.ok?'safe':'warn'">{{audit.ok?'通过':'需检查'}}</span></div></div><template v-if="audit"><div class="audit-meta"><span>审计时间 {{new Date(audit.checkedAt).toLocaleString()}}</span><span>规则版本：Source Engine</span></div><p v-if="audit.notice" class="audit-notice">{{audit.notice}}</p><div class="audit-list"><div v-for="stage in audit.stages" :key="stage.stage"><span>{{stage.stage}}</span><b :class="{good:stage.ok}">{{stage.ok?'通过':'失败'}}</b><small>{{stage.durationMs}}ms</small><p v-if="stage.message">{{stage.message}}</p><p v-if="!stage.ok&&compatibilityTip(stage.message)" class="compat-tip">建议：{{compatibilityTip(stage.message)}}</p></div></div></template><div v-else class="detail-empty"><span>✓</span><h3>逐项确认来源与播放策略</h3><p>点击来源列表中的“审计”，验证分类、搜索、详情、播放地址解析与 Runtime 状态。</p></div></aside></div>

<dialog :open="editOpen" class="source-dialog"><article v-if="editOpen"><h3>编辑点播来源</h3><label>名称<input v-model="editDraft.name" maxlength="80"/></label><label>接口地址<input v-model="editDraft.endpoint"/></label><label>Ext / 规则<input v-model="editDraft.ext"/></label><label>JAR<input v-model="editDraft.jar"/></label><div class="row-actions"><button class="primary-button" :disabled="!editDraft.name.trim()||!editDraft.endpoint.trim()" @click="saveEdit">保存</button><button class="secondary-button" @click="editOpen=false">取消</button></div></article></dialog>
<dialog :open="editLiveOpen" class="source-dialog"><article v-if="editLiveOpen"><h3>编辑直播来源</h3><label>名称<input v-model="editLiveDraft.name"/></label><label>EPG 地址<input v-model="editLiveDraft.epg" placeholder="XMLTV EPG URL（可留空）"/></label><label>User-Agent<input v-model="editLiveDraft.userAgent" placeholder="可留空"/></label><div class="row-actions"><button class="primary-button" :disabled="!editLiveDraft.name.trim()" @click="saveEditLive">保存</button><button class="secondary-button" @click="editLiveOpen=false">取消</button></div></article></dialog>
<dialog :open="Boolean(deleteDraft)" class="source-dialog danger-dialog"><article v-if="deleteDraft"><h3>删除{{deleteDraft.kind==='group'?'导入源':deleteDraft.kind==='vod'?'点播来源':'直播来源'}}「{{deleteDraft.name}}」</h3><p class="danger-note">此操作不可恢复，将级联删除以下关联数据（实时统计）：</p><ul class="cascade-list"><li v-for="item in deleteDraft.counts" :key="item.label"><span>{{item.label}}</span><b>{{item.count}}</b></li></ul><label>输入来源名称以确认：<input v-model="deleteDraft.confirmText" :placeholder="deleteDraft.name"/></label><div class="row-actions"><button class="secondary-button" @click="deleteDraft=null">取消</button><button class="danger-button" :disabled="!deleteReady()" @click="confirmDelete">确认删除</button></div></article></dialog></section></template>

