var(--line);border-radius:999px;background:var(--surface);color:var(--muted);font-size:10px;font-weight:700;white-space:nowrap}.compat-badge.compatible,.compat-badge.safe{border-color:color-mix(in srgb,var(--good) 38%,var(--line));background:color-mix(in srgb,var(--good) 10%,var(--surface));color:var(--good)}.compat-badge.incompatible,.compat-badge.danger{border-color:color-mix(in srgb,var(--danger) 38%,var(--line));background:color-mix(in srgb,var(--danger) 9%,var(--surface));color:var(--danger)}.compat-badge.pending{background:var(--accent-soft);color:var(--accent)}.bulk-toolbar{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:10px}.bulk-toolbar>div:first-child{display:flex;flex-direction:column;gap:4px}.source-group-row td{padding:0!important;background:var(--surface-2);border-bottom:1px solid var(--line)}.source-group-heading{min-height:54px;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:9px 12px}.source-group-heading>div:first-child{display:flex;flex-direction:column;gap:3px}.source-group-heading small{font-size:10px}.live-source-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:22px 0 10px;padding-top:18px;border-top:1px solid var(--line)}.playlist-group-title{display:flex;align-items:center;gap:10px;margin:14px 0 6px}.playlist-group-title small{color:var(--muted)}.live-source-table code{display:block;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted)}.compat-tip{display:block;color:var(--warning,#9a681f);font-size:10px;margin-top:4px;max-width:240px}.audit-meta{display:flex;flex-direction:column;gap:3px;font-size:10px;color:var(--muted);margin-bottom:8px}.audit-notice{margin:8px 0;padding:8px 10px;border-radius:8px;background:var(--accent-soft,#eef4ff);color:var(--accent,#3b6fd4);font-size:11px;line-height:1.6}@media(max-width:900px){.bulk-toolbar,.source-group-heading,.live-source-heading{align-items:flex-start;flex-d